def test_human_triage_excludes_agent_resolved_table_false_positives_and_row_fragments():
    elements = _load_elements()
    subset_pages = {12, 259, 457, 471}
    extraction = {"elements": [item for item in elements if item.get("page") in subset_pages]}

    tasks = _build_human_triage_tasks(extraction, comparison=None)
    findings = _build_agent_resolved_findings(extraction, comparison=None)

    task_pages = {task["page"] for task in tasks if task.get("kind") == "table_uncertain"}
    finding_pages = {finding["page"] for finding in findings}
    classifications = {finding.get("classification") for finding in findings}

    assert task_pages == set()
    assert {12, 259, 457, 471}.issubset(finding_pages)
    assert TABLE_CLASS_PAGE_FRAME_FALSE_POSITIVE in classifications
    assert TABLE_CLASS_PROSE_FALSE_POSITIVE in classifications
    assert TABLE_CLASS_ROW_FRAGMENT in classifications
    assert TABLE_CLASS_REAL in classifications
    assert all("Is this a real table" not in task["human_question"] for task in tasks)


